-- ── story 2-9a: the GRN document and client confirmation ─────────────────
-- Generated by drizzle-kit (the three columns and the over-receipt index —
-- made IF NOT EXISTS by hand, the 6-2a lint) and hand-amended: the CHECKs
-- (the frozen parties' shape; the attachment pairing, kind and template) and
-- the post-migration probe (drizzle-kit is blind to all of them; `bun run
-- db:generate` afterwards reports "No schema changes").
--
-- Additive: no data statement and NO BACKFILL — a GRN recorded before this
-- migration keeps `document_parties` NULL and its document prints the live
-- parties with a note (freezing today's master into a past document would
-- claim a freeze that never happened). Every existing mail row has no
-- attachment. No foreign keys (IMPLEMENTATION-GUIDE §3). RLS is unchanged on
-- both tables (0013's and 0089's tenant policies cover the new columns).
--
-- Lock cost:
--  - the two ADD COLUMNs are metadata-only (nullable, no default);
--  - `goods_receipt_notes_document_parties_shape` is added NOT VALID and then
--    VALIDATEd as its own statement (A7): every existing row is NULL (the
--    column is new in this migration), so the validation scan only reads,
--    under SHARE UPDATE EXCLUSIVE — the receiving commands keep writing;
--  - the three email_messages CHECKs are added validated: the table is small
--    (0114's 200,000-row guard precedes them; final rows purge at 90 days)
--    and every existing row satisfies them by construction (both columns NULL);
--  - `over_receipts_tenant_grn_line_idx` (D8) is a plain build: over_receipts
--    holds excesses only, so it is small (DEPLOY §5).
ALTER TABLE "email_messages" ADD COLUMN IF NOT EXISTS "attachment_kind" text;--> statement-breakpoint
ALTER TABLE "email_messages" ADD COLUMN IF NOT EXISTS "attachment_ref" uuid;--> statement-breakpoint
ALTER TABLE "goods_receipt_notes" ADD COLUMN IF NOT EXISTS "document_parties" jsonb;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "over_receipts_tenant_grn_line_idx" ON "over_receipts" USING btree ("tenant_id","grn_line_id");--> statement-breakpoint
-- ── hand-amended: the frozen parties' shape (decision 3, A3) ──────────────
-- v 1, a warehouse object, and a client and a vendor each an object or JSON
-- null (every key present). The keys inside are the command's to build
-- (`GrnPartiesSnapshotV1`, inbound/grn-document.types.ts).
-- `coalesce(…, false)`: a missing key makes a comparison NULL, and a CHECK
-- passes on NULL — so absence must read as a refusal (probed below).
ALTER TABLE "goods_receipt_notes" ADD CONSTRAINT "goods_receipt_notes_document_parties_shape" CHECK (
	"document_parties" IS NULL OR coalesce((
		jsonb_typeof("document_parties") = 'object'
		AND "document_parties"->>'v' = '1'
		AND jsonb_typeof("document_parties"->'warehouse') = 'object'
		AND jsonb_typeof("document_parties"->'client') IN ('object', 'null')
		AND jsonb_typeof("document_parties"->'vendor') IN ('object', 'null')
	), false)
) NOT VALID;--> statement-breakpoint
ALTER TABLE "goods_receipt_notes" VALIDATE CONSTRAINT "goods_receipt_notes_document_parties_shape";--> statement-breakpoint
-- ── hand-amended: the email attachment (decision 17) ──────────────────────
-- Both or neither; one kind (`EMAIL_ATTACHMENT_KINDS`, modules/mail/mail-rules.ts
-- — pinned by test/mail.spec.ts); only on the receipt notice.
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_attachment_pairing" CHECK (
	("attachment_kind" IS NULL) = ("attachment_ref" IS NULL)
);--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_attachment_kind_check" CHECK (
	"attachment_kind" IS NULL OR "attachment_kind" IN ('grn-pdf')
);--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_attachment_template_check" CHECK (
	"attachment_kind" IS NULL OR "template" = 'client-receipt'
);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0089/0103/0114 model) ──────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (each violates only its target).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	w jsonb := '{"code":"W1","name":"Main","gstin":null,"address":null,"operatorName":"Probe 3PL"}'::jsonb;
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: NULL parties; client and vendor null; a full
	-- object; a receipt notice with a GRN PDF; a row with neither column.
	BEGIN
		INSERT INTO "goods_receipt_notes" ("id","tenant_id","warehouse_id","code","po_id","status","device_id","recorded_by","occurred_at","recorded_at","document_parties")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-1', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(), NULL),
		       (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-2', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(),
		        jsonb_build_object('v', 1, 'warehouse', w, 'client', NULL::jsonb, 'vendor', NULL::jsonb) || '{"client":null,"vendor":null}'::jsonb),
		       (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-3', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(),
		        jsonb_build_object('v', 1, 'warehouse', w, 'client', '{"v":1,"code":"ACME"}'::jsonb, 'vendor', '{"v":1,"code":"V1"}'::jsonb));
		INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
		VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:g1:a@example.in', 1, 'grn-pdf', gen_random_uuid()),
		       (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:g2:a@example.in', 1, NULL, NULL);
		RAISE EXCEPTION USING ERRCODE = 'P0115', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0115: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0115' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'parties v 2',
		'parties without a warehouse',
		'parties with a string client',
		'parties without a client key',
		'attachment kind without a ref',
		'attachment ref without a kind',
		'unknown attachment kind',
		'grn-pdf on an invite'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'attachment kind without a ref' THEN 'email_messages_attachment_pairing'
			WHEN 'attachment ref without a kind' THEN 'email_messages_attachment_pairing'
			WHEN 'unknown attachment kind' THEN 'email_messages_attachment_kind_check'
			WHEN 'grn-pdf on an invite' THEN 'email_messages_attachment_template_check'
			ELSE 'goods_receipt_notes_document_parties_shape'
		END;
		BEGIN
			CASE probe
				WHEN 'parties v 2' THEN
					INSERT INTO "goods_receipt_notes" ("id","tenant_id","warehouse_id","code","po_id","status","device_id","recorded_by","occurred_at","recorded_at","document_parties")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-X', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(),
					        jsonb_build_object('v', 2, 'warehouse', w) || '{"client":null,"vendor":null}'::jsonb);
				WHEN 'parties without a warehouse' THEN
					INSERT INTO "goods_receipt_notes" ("id","tenant_id","warehouse_id","code","po_id","status","device_id","recorded_by","occurred_at","recorded_at","document_parties")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-X', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(),
					        '{"v":1,"client":null,"vendor":null}'::jsonb);
				WHEN 'parties with a string client' THEN
					INSERT INTO "goods_receipt_notes" ("id","tenant_id","warehouse_id","code","po_id","status","device_id","recorded_by","occurred_at","recorded_at","document_parties")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-X', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(),
					        jsonb_build_object('v', 1, 'warehouse', w, 'client', 'ACME') || '{"vendor":null}'::jsonb);
				WHEN 'parties without a client key' THEN
					INSERT INTO "goods_receipt_notes" ("id","tenant_id","warehouse_id","code","po_id","status","device_id","recorded_by","occurred_at","recorded_at","document_parties")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), 'PROBE-0115-X', gen_random_uuid(), 'recorded', gen_random_uuid(), gen_random_uuid(), now(), now(),
					        jsonb_build_object('v', 1, 'warehouse', w) || '{"vendor":null}'::jsonb);
				WHEN 'attachment kind without a ref' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
					VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:x:a@example.in', 1, 'grn-pdf', NULL);
				WHEN 'attachment ref without a kind' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
					VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:x:a@example.in', 1, NULL, gen_random_uuid());
				WHEN 'unknown attachment kind' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
					VALUES (gen_random_uuid(), t, 'client-receipt', 'a@example.in', '{}', 'pending', now(), c, 'client-receipt:x:a@example.in', 1, 'invoice-pdf', gen_random_uuid());
				WHEN 'grn-pdf on an invite' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at","client_id","dedupe_key","priority","attachment_kind","attachment_ref")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'pending', now(), NULL, NULL, 0, 'grn-pdf', gen_random_uuid());
			END CASE;
			RAISE EXCEPTION USING ERRCODE = 'P0115', MESSAGE = 'a refused probe landed';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0115' THEN
				RAISE EXCEPTION 'migration 0115: the probe "%" was accepted.', probe;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0115: the probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "goods_receipt_notes" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0115: a probe row survived.';
	END IF;
END $$;
